<script setup lang="ts">import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAppStore } from '@/stores/app'; const app=useAppStore(); const router=useRouter(); const form=ref({name:'',key:'',description:'',color:'#00a9ad'}); async function submit(){const p=await app.createProject(form.value);router.push(`/projects/${p.id}/overview`)}</script>
<template><div class="page narrow-page"><header class="page-header"><div><h1>Create project</h1><p>Create a focused space for related work.</p></div></header><form class="panel form-stack" @submit.prevent="submit"><label>Project name<input v-model="form.name" required placeholder="Example: Web Experience"/></label><label>Key<input v-model="form.key" required maxlength="8" placeholder="WEB"/><small>Used in task identifiers such as WEB-42.</small></label><label>Description<textarea v-model="form.description" rows="4" placeholder="What is this project responsible for?"></textarea></label><label>Project color<input v-model="form.color" type="color"/></label><div class="modal-actions"><RouterLink class="btn" to="/projects">Cancel</RouterLink><button class="btn btn-primary">Create project</button></div></form></div></template>
